const crypto = require('crypto');
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const receiptUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!/\/receipt$/.test(receiptUrl)) throw new Error('automation_control_receipt_url_invalid');
const executionId = String($execution.id || '').trim();
if (!executionId) throw new Error('missing_execution_id');
const body = JSON.stringify({
  heartbeat_key:'n8n-runtime',
  workflow_version:'v1',
  execution_id:executionId.slice(0,255),
  occurred_at:new Date().toISOString()
});
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + body, 'utf8')
  .digest('hex');
return [{json:{
  heartbeat_url:receiptUrl.replace(/\/receipt$/, '/heartbeat'),
  heartbeat_body:body,
  heartbeat_timestamp:timestamp,
  heartbeat_signature:signature
}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) {
  throw new Error('automation_heartbeat_failed_http_' + statusCode);
}
const body = response.body || {};
if (body.accepted !== true || body.heartbeat_key !== 'n8n-runtime') {
  throw new Error('automation_heartbeat_not_accepted');
}
return [{json:{
  recorded:true,
  heartbeat_key:body.heartbeat_key,
  received_at:body.received_at,
  beat_count:Number(body.beat_count || 0),
  duplicate:Boolean(body.duplicate)
}}];
